function translateDOM(){const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walk.nextNode())nodes.push(walk.currentNode);for(const n of nodes){if(n.parentElement?.closest('script,style,pre,.catface,.shell-output'))continue;const trim=n.textContent.trim();const known=nodeOriginal.get(n);let original=known;if(!known||!phrases.some(r=>r.includes(trim)&&r[0]===known)){original=reverse.get(trim)||trim;nodeOriginal.set(n,original)}const row=lookup.get(original);if(row){const value=row[language==='pl'?1:language==='ru'?2:0];if(trim!==value)n.textContent=n.textContent.replace(trim,value)}}}
